% Build the Simulink model ipmsm_2kw_fvc.slx in the folder of this script.
% Generated by motulator_plecs.simulink from motulator. The parameters of
% the control system are in the mask of the subsystem 'Flux-vector control',
% and those of the system model in the model workspace.
%
% The S-function sfun_flux_vector_control.c is compiled with mex, which needs a C99
% compiler with complex.h (gcc, clang, or MinGW-w64, not MSVC), see
% mex -setup C.

here = fileparts(mfilename('fullpath'));
addpath(fullfile(here, '..', '..', 'motulator_plecs', 'simulink'));

s = struct();
s.folder = here;
s.name = 'ipmsm_2kw_fvc';
s.init = strjoin({ ...
    'machine.n_p = 3.0;', ...
    'machine.R_s = 3.6;', ...
    'machine.L_d = 0.036;', ...
    'machine.L_q = 0.051;', ...
    'machine.psi_f = 0.545;', ...
    'mechanics.J = 0.015;', ...
    'converter.u_dc = 540.0;'}, newline);
s.machine = 'sm';
s.w_M_ref = [0.0999375 0.0 50.0];
s.tau_L = [0.7 0.0 10.0];
s.scope = { ...
    'Speed', [7.0 8.0 4.0]
    'Torque', [9.0 10.0 6.0]
    'Current', [1.0 2.0 3.0]
    'Flux', [11.0 12.0]
